WITH lines AS (SELECT id, host, log_ts, latency_ms, status_code, attr_key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) x AS attr_key, attr_value) SELECT CASE WHEN status_code >= 387 THEN 'PREMIUM' ELSE 'STANDARD' END AS status_code_tier, MAX(log_ts) AS last_seen, APPROX_PERCENTILE(status_code, ARRAY(0.25, 0.5, 0.75)) AS status_code_quartiles, MIN(log_ts) AS started_at FROM lines GROUP BY CASE WHEN status_code >= 387 THEN 'PREMIUM' ELSE 'STANDARD' END
